import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../models/booking.dart';
import '../../viewmodels/auth_view_model.dart';
import '../../viewmodels/booking_view_model.dart';
import '../../theme/app_theme.dart';

class TutorEarningsScreen extends StatelessWidget {const TutorEarningsScreen({super.key});
@override Widget build(BuildContext context){final auth=context.watch<AuthViewModel>();final all=context.watch<BookingViewModel>().forTutor(auth.userName);final completed=all.where((b)=>b.status==BookingStatus.completed).toList();final upcoming=all.where((b)=>b.status==BookingStatus.upcoming).toList();final earned=completed.fold<int>(0,(sum,b)=>sum+b.price);final expected=upcoming.fold<int>(0,(sum,b)=>sum+b.price);return Scaffold(appBar:AppBar(title:const Text('Earnings')),body:ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:AppColors.blue,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Completed session value',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text('R $earned',style:const TextStyle(color:Colors.white,fontSize:32,fontWeight:FontWeight.w800)),const SizedBox(height:6),Text('${completed.length} completed sessions',style:const TextStyle(color:Colors.white70))])),const SizedBox(height:14),Card(child:ListTile(leading:const Icon(Icons.pending_actions,color:AppColors.blue),title:const Text('Upcoming session value'),trailing:Text('R $expected',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17)))),const SizedBox(height:20),const Text('Completed sessions',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),const SizedBox(height:8),if(completed.isEmpty)const Padding(padding:EdgeInsets.all(18),child:Text('Completed sessions will appear here.',style:TextStyle(color:AppColors.textMuted)))else ...completed.map((b)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(b.subject),subtitle:Text('${b.learnerName} • ${formatDate(b.start)}'),trailing:Text('R ${b.price}',style:const TextStyle(fontWeight:FontWeight.w700)))) ,const SizedBox(height:16),const Text('Note: These are estimates based on booking prices. Actual payments and payouts are not connected yet.',style:TextStyle(color:AppColors.textMuted,fontSize:12))]));}
}
